/* Saving Planets app helper (generated by scripts/build-pwa.py): registers the service worker only. Nov 3 2026 (founder): the "Get the Saving Planets app" install banner was removed; browser install mini-bars are suppressed too. */
(function () {
  if ('serviceWorker' in navigator) addEventListener('load', function () { navigator.serviceWorker.register('/sw.js').catch(function () {}); });
  addEventListener('beforeinstallprompt', function (e) { e.preventDefault(); });
  try { localStorage.removeItem('sp-install-dismissed'); } catch (e) {}
})();
